changeSet.sql:
CREATE TEMP TABLE tmp_deferred_fix AS SELECT id, bill_account_id, household_id, year, month, base_amount FROM bill_account_amounts WHERE is_deferred = true AND base_amount > 0;
INSERT INTO bill_account_amounts ( id, bill_account_id, household_id, year, month, base_amount, carried_amount, amount, status, is_deferred ) SELECT gen_random_uuid(), t.bill_account_id, t.household_id, CASE WHEN t.month = 12 THEN t.year + 1 ELSE t.year END, CASE WHEN t.month = 12 THEN 1 ELSE t.month + 1 END, 0, t.base_amount, t.base_amount, 'NOT_CONFIRMED', false FROM tmp_deferred_fix t ON CONFLICT DO NOTHING;
UPDATE bill_account_amounts target SET carried_amount = COALESCE(target.carried_amount, 0) + t.base_amount, amount = COALESCE(target.base_amount, 0) + COALESCE(target.carried_amount, 0) + t.base_amount FROM tmp_deferred_fix t WHERE target.bill_account_id = t.bill_account_id AND target.household_id = t.household_id AND target.year = CASE WHEN t.month = 12 THEN t.year + 1 ELSE t.year END AND target.month = CASE WHEN t.month = 12 THEN 1 ELSE t.month + 1 END;
UPDATE bill_account_amounts b SET base_amount = 0, amount = COALESCE(carried_amount, 0) FROM tmp_deferred_fix t WHERE b.id = t.id;
DROP TABLE tmp_deferred_fix;
